package com.cryptostrategy.platform.combination.api;
import com.cryptostrategy.platform.combination.internal.CompositeStrategy;import com.cryptostrategy.platform.strategy.api.Strategy;import com.cryptostrategy.platform.strategy.api.model.StrategyReference;import java.util.*;
public final class CompositeStrategyFactory {private final Map<CombinationPolicyReference,CombinationPolicy> policies;public CompositeStrategyFactory(List<CombinationPolicy> policies){Map<CombinationPolicyReference,CombinationPolicy> map=new HashMap<>();for(var policy:policies)if(map.putIfAbsent(policy.reference(),policy)!=null)throw new IllegalArgumentException("Duplicate policy");this.policies=Map.copyOf(map);}public Strategy create(StrategyReference reference,CombinationPolicyReference policyReference,List<Strategy> components){CombinationPolicy policy=policies.get(policyReference);if(policy==null)throw new IllegalArgumentException("Combination policy unavailable");return new CompositeStrategy(reference,policy,components);}}
